create or replace function app_transition_documents_status() returns trigger
    language plpgsql security definer set search_path = public, pg_temp
as $$
declare
    v_actor text;
begin
    if old.status is not distinct from new.status then
        return new;
    end if;
    if not exists (select 1 from state_transitions t where t.machine = any (array['document']::text[]) and t.from_state = old.status and t.to_state = new.status) then
        raise exception 'illegal transition of documents.status: % -> %', old.status, new.status
            using errcode = '23514';
    end if;
    return new;
end
$$;
revoke all on function app_transition_documents_status() from public;
drop trigger if exists transition_status on documents;
create trigger transition_status before update of status on documents
    for each row execute function app_transition_documents_status();

