create or replace function app_transition_memberships_status() returns trigger
    language plpgsql security definer set search_path = public, pg_temp
as $$
declare
    v_user  uuid := nullif(current_setting('app.user_id', true), '')::uuid;
    v_tool  text := nullif(current_setting('app.actor', true), '');
    v_actor text;
begin
    if old.status is not distinct from new.status then
        return new;
    end if;
    if not exists (select 1 from state_transitions t where t.machine = any (array['membership']::text[]) and t.from_state = old.status and t.to_state = new.status) then
        raise exception 'illegal transition of memberships.status: % -> %', old.status, new.status
            using errcode = '23514';
    end if;
    if v_user is null then
        v_actor := case when v_tool is not null then 'system'
                        when session_user = 'lmqa_owner' then 'owner' end;
    elsif v_user = old.user_id then
        v_actor := 'member';
    elsif exists (select 1 from memberships m
                  where m.user_id = v_user and m.status = 'active'
                    and ((old.role = 'admin' and m.role = 'super_admin' and m.org_id = old.org_id)
                         or (old.role = 'tenant' and m.role = 'admin' and m.workspace_id = old.workspace_id))) then
        v_actor := 'approver';
    else
        v_actor := 'other';
    end if;
    if v_actor is distinct from 'owner' and not exists (select 1 from state_transitions t where t.machine = any (array['membership']::text[]) and t.from_state = old.status and t.to_state = new.status and v_actor = any (t.actors)) then
        raise exception 'actor % may not move memberships.status: % -> %',
            coalesce(v_actor, 'none'), old.status, new.status using errcode = '42501';
    end if;
    return new;
end
$$;
revoke all on function app_transition_memberships_status() from public;
drop trigger if exists transition_status on memberships;
create trigger transition_status before update of status on memberships
    for each row execute function app_transition_memberships_status();

create or replace function app_transition_workspaces_status() returns trigger
    language plpgsql security definer set search_path = public, pg_temp
as $$
declare
    v_user  uuid := nullif(current_setting('app.user_id', true), '')::uuid;
    v_tool  text := nullif(current_setting('app.actor', true), '');
    v_actor text;
begin
