    if not exists (select 1 from state_transitions t where t.machine = any (array['workspace']::text[]) and t.from_state = old.status and t.to_state = new.status) then
        raise exception 'illegal transition of workspaces.status: % -> %', old.status, new.status
            using errcode = '23514';
    end if;
    if v_user is null then
        v_actor := case when v_tool is not null then 'system'
                        when session_user = 'lmqa_owner' then 'owner' end;
    elsif exists (select 1 from memberships m where m.user_id = v_user and m.status = 'active'
                  and m.role = 'super_admin' and m.org_id = old.org_id) then
        v_actor := 'super_admin';
    elsif exists (select 1 from memberships m where m.user_id = v_user and m.status = 'active'
                  and m.role = 'admin' and m.workspace_id = old.id) then
        v_actor := 'admin';
    else
        v_actor := 'other';
    end if;
    if v_actor is distinct from 'owner' and not exists (select 1 from state_transitions t where t.machine = any (array['workspace']::text[]) and t.from_state = old.status and t.to_state = new.status and v_actor = any (t.actors)) then
        raise exception 'actor % may not move workspaces.status: % -> %',
            coalesce(v_actor, 'none'), old.status, new.status using errcode = '42501';
    end if;
    return new;
end
