create or replace function app_not_self_memberships() returns trigger
    language plpgsql security definer set search_path = public, pg_temp
as $$
declare
    v_user uuid := nullif(current_setting('app.user_id', true), '')::uuid;
begin
    if v_user is null or v_user is distinct from old.user_id then
        return coalesce(new, old);
    end if;
    if tg_op = 'DELETE' then
        if old.status = any (array['pending_approval']::text[]) then
            return old;
        end if;
        raise exception 'a member cannot delete their own memberships row in state %', old.status
            using errcode = '42501';
    end if;
    raise exception 'a member cannot change their own memberships row' using errcode = '42501';
end
$$;
revoke all on function app_not_self_memberships() from public;
drop trigger if exists memberships_not_self on memberships;
create trigger memberships_not_self before update of status, approver_id, decided_at, state_reason, co_owner, owner_linked or delete on memberships
    for each row execute function app_not_self_memberships();

